-- First pass of table and function comments. Metadata only, no behaviour change.
-- Pattern: what it holds · who fills it and how often · whether Claude may write.
comment on table public.meetings is 'Fathom recordings for the whole team (title, summary, transcript, participants, share_url). Filled by fathom-sync every 6h. Read first for any call; use meetings_unique for counts. Read-only except meeting_insight_save().';
comment on table public.meeting_insights is 'Transcript-based summary, decisions, tasks and conflicts per recording. Read via meeting_insight_get(). Written by the meeting jobs.';
comment on table public.meeting_agendas is 'Pre-meeting agendas per team meeting, built by the agendas ai_job from meeting_schedule / meetings_on().';
comment on table public.sync_state is 'fathom-sync bookmark per teammate (synced_until, last_run_at) plus a few routine bookmarks. Read to check freshness; never edit by hand.';
comment on table public.fathom_webhooks is 'Raw Fathom webhook deliveries. Log only.';
comment on table public.knowledge is 'Team facts by kind (rule, client, process, decision, offer, metric, tool, person, slack_channel). Supersede with superseded=true, never delete. kind=slack_channel is the channel guide.';
comment on table public.memory_chunks is 'Embedded chunks of Slack, meetings and EODs behind ioc_search(). Filled by mem_kick() every minute. Read through ioc_search(), not directly.';
comment on table public.clients is 'Resolved client index (aliases, IG, phone, Asana gid, ad account, tracker sheet). Always look up via find_client(). Write back resolved fields with field_sources. Asana is the source of the client list.';
comment on table public.team_members is 'IOC team: Slack id, GHL user id, Asana gid, team, reports_to, work days, personal rules. Edited by Sahil; read via person_card().';
comment on table public.slack_messages is 'Every message in channels IOCtopus is in, realtime from slack-events. Query the view slack_messages_ist (IST times, channel names) or slack_search() / ioc_search().';
comment on table public.slack_channels is 'Channels IOCtopus knows, with backfill state. is_member = bot is in it.';
comment on table public.slack_outbox is 'The only way to post to Slack as the bot: insert (channel_id, thread_ts, text, purpose draft|final|chat|nudge), then read status/slack_ts/error. Sent by send_slack_outbox().';
comment on table public.wa_messages is 'Team WhatsApp DMs with IOCtopus (both directions), realtime from whatsapp-webhook. Never clients.';
comment on table public.wa_outbox is 'The only way to send WhatsApp as the bot: insert (to_number, text, reply_to, reply_id, purpose). Sent by send_wa_outbox(). Team members only, never clients.';
comment on table public.email_outbox is 'Queued outbound emails (drive-share, invoice flows). Insert only where a skill says so.';
comment on table public.ghl_contacts is 'GHL contacts copy with attribution (utm_*, first/last touch). Filled by ghl-sync every 6h. For anything live use the GHL connector. Read-only.';
comment on table public.ghl_opportunities is 'GHL Sales Pipeline opportunities copy (stage_id -> stage_map, custom_fields). Filled by ghl-sync every 6h + webhooks. Use the pipeline_cards view for flattened fields. Never change stages here or in GHL.';
comment on table public.ghl_appointments is 'GHL appointments copy for the 7 strategy-call calendars (app_config.ioc_live_calendars). Filled by ghl-closer-sync every 2h. Read-only.';
comment on table public.ghl_events is 'Stage/status change events from GHL webhooks (realtime). Use for "when did X move to Y".';
comment on table public.ghl_calendar_events is 'Team calendar blocks copied from GHL (internal meetings, blocked slots). Filled by ghl-calendar-events.';
comment on table public.ghl_transactions is 'GHL payment transactions copy, every 2h. Use ghl_transactions_real for real money (excludes test/zero). Never record or confirm payments.';
comment on table public.ghl_invoices is 'GHL invoices copy. Drafts are created only through ghl_invoice_draft() (invoices skill). Never send invoices.';
comment on table public.invoice_drafts is 'Draft invoices the bot created in GHL, who asked, Slack thread. Written by ghl-invoice-draft.';
comment on table public.invoice_actions is 'Edits/actions on invoice drafts via the bot. Log.';
comment on table public.stage_map is 'GHL Sales Pipeline stage_id -> name, position, milestone. Join from ghl_opportunities.stage_id.';
comment on table public.ghl_lost_reasons is 'GHL lost-reason id -> label.';
comment on table public.closers is 'Sales closers (GHL user id, display name, active) for dashboards and routing.';
comment on table public.ghl_sync_runs is 'Run log of ghl-sync (started, finished, counts, error). Read first when checking whether GHL data is fresh.';
comment on table public.meta_sync_runs is 'Run log of meta-sync. Read first when checking Meta freshness.';
comment on table public.meta_ads is 'IOC Meta ads (campaign, adset, ad, status). Filled by meta-sync daily. Read-only.';
comment on table public.meta_insights_daily is 'IOC Meta ad metrics per ad per day (spend, clicks, leads, video). Filled by meta-sync 06:45 and 09:45 IST. Use ad_daily_funnel / ad_creative_daily views for reports.';
comment on table public.client_ad_accounts is 'Client Meta ad account ids, linked to clients. Filled by the Fulfilment Data Sync.';
comment on table public.gcal_events is 'Google Calendar events from the connected accounts in google_accounts (push watches). Live source for meeting times; merge with GHL and meeting_schedule before saying anyone is free.';
comment on table public.google_accounts is 'Connected Google accounts (email, scopes, watch state). refresh_token is a secret: never select it. Actions go through public.google().';
comment on table public.google_actions is 'Log of actions taken through public.google() (sends, edits) with the confirming asker.';
comment on table public.asana_proposals is 'Asana task proposals awaiting approve in Slack (asana-tasks skill). Created only after approve via asana_proposal_done().';
comment on table public.task_sync is 'Teams Tasks rows mirrored to Asana (row_id <-> asana gid). Written by task-sync.';
comment on table public.task_sync_log is 'Run log of task-sync. Read to check whether a task reached Asana.';
comment on table public.teams_tasks is 'Team Tasks Slack List rows (task, owner, due, done, approval). Mirrored hourly by task-sync. Change via team_task_add()/team_task_update(), own tasks only.';
comment on table public.team_lists is 'Slack List ids and column maps per team (tasks, agendas).';
comment on table public.all_tasks_map is 'Legacy all-teams tasks list map. Kept for history; use teams_tasks.';
comment on table public.ig_profiles is 'Cache of public Instagram profile reads made by the ig-profile edge function (lead-notes research). Refreshed when older than 24h. Read via ig_profile().';
comment on table public.content_posts is 'IOC Instagram posts with metrics (content-ig-sync daily 07:57 IST). Content team dashboard source.';
comment on table public.content_state is 'Content pipeline state per item from the content Google Sheet (content-wake every 15 min).';
comment on table public.content_settings is 'Content pipeline settings (sheet ids, channels). Edit only on request.';
comment on table public.eod_drafts is 'Per-person EOD drafts (eod_drafts ai_job 19:58 IST) and their confirmations. Posted by eod_post_all() at 23:00. Never post EODs by hand.';
comment on table public.eod_posts is 'EODs actually posted in #team-eods, with Slack ts.';
comment on table public.eod_formats is 'EOD section formats per team/person.';
comment on table public.skills is 'IOCtopus skills: the bot know-how, loaded with skill_load(slug) and changed only with skill_write() (versioned, tested). active=false rows are drafts under review. core is locked.';
comment on table public.skill_versions is 'Every version of every skill (body, change_note, author). skill_undo() restores the previous one.';
comment on table public.skill_tests is 'Per-skill tests: kind must_keep (regex the body must contain, enforced by skill_write) and scenario (question + expected, checked nightly).';
comment on table public.bot_rules is 'Rules trained by Aakash/Sahil in DM via bot_rule_save(). Read with bot_rules_list(). active=false when removed; never delete.';
comment on table public.bot_notes is 'Observations and queued edits the bot could not apply (locked skill, edit limit). The nightly review merges them.';
comment on table public.bot_feedback is 'Reactions on bot replies (good/bad) linked to the outbox row and reply trace. Review via bot_feedback_review view; feeds the nightly daily_review job.';
comment on table public.reply_traces is 'Per bot reply: question, asker, skills loaded, rules shown. Join to bot_feedback to see which skill a bad answer used.';
comment on table public.bot_actions is 'Log of every message the bot sent on someone''s behalf (notify, dm, reminder, ghl_cancel). Required by the permissions skill.';
comment on table public.bot_jobs is 'Recurring bot jobs (sql / check / ai tiers) created with job_save(); run by jobs_tick() every minute. Runs in bot_job_runs.';
comment on table public.bot_job_runs is 'Run log of bot_jobs.';
comment on table public.bot_reminders is 'Timed reminders created with reminder_add(); cancelled with reminder_cancel().';
comment on table public.bot_open_loops is 'Open asks, promises and deadlines the AI-employee scan nudges about; closed with loop_close().';
comment on table public.app_config is 'Key/value config for every job and the bot. Keys containing secret, token, key or pin are secrets: never select or repeat their values. ai_tool_guide is the shared preamble for ai_jobs.';
comment on table public.ai_jobs is 'Supabase-side Claude jobs (lead_notes, note2, eod_drafts, agendas, daily_review, pipeline_sync, ad_report...): instructions, tools, model, shadow flag. These replaced the Claude scheduled tasks. Edit instructions only on request.';
comment on table public.ai_queue is 'Queue of ai_jobs runs (ai_enqueue -> ai_tick every 2 min). Status and result per run.';
comment on table public.ai_usage is 'Tokens, cost and duration per ai_jobs run. ai_cost_daily view sums it. Read for cost questions.';
comment on table public.job_locks is 'Advisory locks for jobs (job_lock/job_unlock). Internal.';
comment on table public.people_availability is 'Leave, half days, travel per person (people_away_add). Checked automatically before nudges.';
comment on table public.people_actions is 'Every tag, DM, nudge and reminder sent per person. Logged automatically.';
comment on table public.ioc_app_events is 'Raw GHL webhook deliveries to ioc-app-events (bookings, status changes, DQ). Log; the Slack posts are in ioc_live_posts.';
comment on table public.ioc_live_posts is 'Booking / confirmed / no-show / disqualified / FCB alert posts made to the appointments channels. A new row wakes the lead_notes ai_job.';
comment on table public.sales_call_note2 is 'Post-call Note 2 per sales appointment written by the note2 ai_job. The job owns Note 2; never write one by hand.';
comment on table public.lead_notes_added is 'Pre-call Note 1 / Disqualified notes written by the lead_notes ai_job, per appointment or application.';
comment on table public.note2_fires is 'Note 2 job wake-ups (recording -> appointment match). Log.';
comment on table public.sales_call_log_rows is 'Sales Call Log Slack List rows (one per sales call) filled every 10 min by sales-call-log. Read via sales_call_log_v.';
comment on table public.wa_history_hold is 'Temporary hold of WhatsApp history before review; purged hourly by cron.';
comment on table public.ws_sessions is 'IOC AI Coach web sessions (separate product). Not IOC team data.';
comment on table public.coach_clients is 'IOC AI Coach product: coaches'' clients. Separate product, do not mix with IOC team or sales data.';
comment on table public.food_db is 'IOC AI Coach food database (search with food_search()). Separate product.';
comment on table public.exercise_db is 'IOC AI Coach exercise database. Separate product.';
comment on table public.meetings_topics_backup_20260929 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.clients_backup_20261027 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.all_tasks_map_backup_20261003 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.client_wa_reports_backup_20261104 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.client_wa_reports_backup_20261104_run1 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.client_wa_reports_backup_20261104_run2 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.client_wa_reports_backup_20261104_run3 is 'Frozen backup. Do not read for answers, do not write.';
comment on table public.fix_rows_20261003 is 'Scratch from the 3 Oct 2026 pipeline cleanup. Do not use.';
comment on table public.fix_plan_20261003 is 'Scratch from the 3 Oct 2026 pipeline cleanup. Do not use.';
comment on table public.fix_owner_scan2_20261003 is 'Scratch from the 3 Oct 2026 pipeline cleanup. Do not use.';
comment on table public.dupe_cleanup_20261003 is 'Scratch from the 3 Oct 2026 Asana duplicate cleanup. Do not use.';
comment on table public.dup_cleanup_log is 'Log of the Asana duplicate cleanup. History only.';
comment on table public.gemini_test_results is 'Old model test output. Do not use.';

comment on function public.skill_load(text) is 'Load a bot skill by slug (active only); bumps load_count. Call before any task a skill covers. Returns the list of slugs if not found.';
comment on function public.skill_write(text, text, text, text, text, text, text, text, text, boolean) is 'Save a new version of a skill (full body). Enforces trainer rules, daily edit limits, 60% shrink guard and must_keep tests. Use instead of updating skills directly.';
comment on function public.skill_undo(text, text, text, text) is 'Restore the previous version of a skill (Aakash/Sahil only).';
comment on function public.ioc_search(text, integer, text, timestamp with time zone, text) is 'Search Slack history and meeting summaries by meaning + keywords. Returns score, time, who, channel, link, snippet. Scores >= 24 are strong. 3rd arg: channel id, null, or ''meetings''.';
comment on function public.slack_search(text, text, integer, integer) is 'Exact-word search over stored Slack messages: query, channel name part or null, days back, limit.';
comment on function public.meeting_insight_get(text, integer) is 'Saved transcript-based summary, decisions, tasks and conflicts for a meeting matching a name or topic within N days. Check before reading raw transcripts.';
comment on function public.meetings_on(date) is 'IOC team meetings on a day: synced Google Calendar times first, fixed meeting_schedule as fallback.';
comment on function public.send_slack_outbox() is 'Sends pending slack_outbox rows as the bot. Runs from triggers/cron; do not post to Slack any other way.';
comment on function public.send_wa_outbox() is 'Sends pending wa_outbox rows as the bot (team numbers only).';
comment on function public.ai_enqueue(text, text, text, text) is 'Queue an ai_jobs run: job slug, payload text, ref, dedupe key. Picked up by ai_tick() within 2 minutes.';
comment on function public.find_client(text, integer) is 'Resolve any rough client reference (misspelling, nickname, brand, IG handle, phone, email) to the client row. Always call this first for any client question. Take the top row if score >= 0.85.';
